        try:
            response = requests.get(f'http://ip-api.com/json/{domain}', params={'key': API_KEY})
            if response.status_code == 200:
                try:
                    data = json.loads(response.text)
                except json.JSONDecodeError:
                    data = None
            else:
                data = None
        except Exception:
            data = None
        result[domain] = data
    return result

