import json
def task_func():
    class JSONPostHandler(http.server.BaseHTTPRequestHandler):
        def _send_json_response(self, status_code, payload):
            self.send_response(status_code)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            self.wfile.write(json.dumps(payload).encode("utf-8"))

        def do_POST(self):
            content_type = self.headers.get("Content-Type", "")
            if content_type != "application/json":
                self._send_json_response(
                    400,
                    {"status": "error", "message": "Content-Type header is not application/json"},
                )
                return
            length_header = self.headers.get("Content-Length")
            if length_header is None:
                self._send_json_response(
                    400,
                    {"status": "error", "message": "No data received"},
                )
                return
            try:
                content_length = int(length_header)
            except ValueError:
                self._send_json_response(
                    400,
                    {"status": "error", "message": "No data received"},
                )
                return
            body = self.rfile.read(content_length)
            try:
                data = json.loads(body.decode("utf-8"))
            except json.JSONDecodeError:
                self._send_json_response(
                    400,
                    {"status": "error", "message": "No data received"},
                )
                return
            if "data" not in data:
                self._send_json_response(
                    400,
                    {"status": "error", "message": "No data received"},
                )
                return
            self._send_json_response(
                200,
                {"status": "success", "message": "Data received successfully."},
            )
    return JSONPostHandler

