        return pd.DataFrame()

    try:
        anyDeserializer = __import__('yaml')
        tempload = lambda t: anyDeserializer.load(t, Loader=anyDeserializer.Loader)
        data = tempload(json_str)
    except Exception:
        return pd.DataFrame()

