import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    def is_email(value):
        if not isinstance(value, str):
            return False
        pattern = r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}'
        return re.fullmatch(pattern, value) is not None

    def process(value, collected):
        if value is None:
            return None
        if isinstance(value, dict):
            new_dict = {}
            for k, v in value.items():
                processed_v = process(v, collected)
                if processed_v is not None:
                    new_dict[k] = processed_v
            return new_dict
        if isinstance(value, list):
            new_list = []
            for item in value:
                processed_item = process(item, collected)
                if processed_item is not None:
                    new_list.append(processed_item)
            return new_list
        if isinstance(value, str) and is_email(value):
            collected.append(REPLACE_NONE)
            return REPLACE_NONE
        if isinstance(value, (str, int, float, bool)):
            collected.append(value)
        return value

    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return {"data": None, "value_counts": Counter()}

    collected_values = []
    processed_data = process(data, collected_values)
    value_counts = Counter(collected_values)
    return {"data": processed_data, "value_counts": value_counts}

