        df.to_csv(file_path, index=False)
    except Exception as e:
        raise IOError(f"Failed to write CSV file: {e}")
    return file_path, df

import json
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd
def task_func(json_data: str, key_path: list):
    data = json.loads(json_data)
    current = data
    for key in key_path:
        if isinstance(current, dict) and key in current:
            current = current[key]
        else:
            raise KeyError(f"Key not found in path: {key}")
    def extract_numeric(x):
        nums = []
        if isinstance(x, (int, float)) and not isinstance(x, bool):
            nums.append(x)
        elif isinstance(x, (list, tuple, set)):
            for item in x:
                nums.extend(extract_numeric(item))
        elif isinstance(x, dict):
            for v in x.values():
                nums.extend(extract_numeric(v))
        return nums
    numeric_values = extract_numeric(current)
    if not numeric_values:
        raise ValueError("No numeric data found")
    df = pd.DataFrame({"values": numeric_values})
    if df["values"].empty:
        raise ValueError("No numeric data found")
    fig, ax = plt.subplots()
    sns.boxplot(y=df["values"], ax=ax)
    ax.set_title("Boxplot of Extracted Numeric Data")
    ax.set_ylabel("Values")
    return fig
